// OpenContext SDK Mock for WordPress Plugin Demo
// This is a simplified mock of the TypeScript SDK for demonstration purposes
// In production, this would be the actual compiled SDK from sdk/js/

class OpenContextClient {
    constructor(config) {
        this.config = config;
        this.provider = null;
        this.signer = null;
        this.contracts = {};
        
        this.init();
    }
    
    async init() {
        if (typeof window.ethereum !== 'undefined') {
            this.provider = new ethers.providers.Web3Provider(window.ethereum);
        }
    }
    
    async authenticate() {
        try {
            if (!this.provider) {
                throw new Error('No Web3 provider found');
            }
            
            await this.provider.send("eth_requestAccounts", []);
            this.signer = this.provider.getSigner();
            
            const address = await this.signer.getAddress();
            
            // Mock passport creation/retrieval
            const passport = {
                id: Math.floor(Math.random() * 10000),
                owner: address,
                dataHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
                created: Date.now()
            };
            
            console.log('OpenContext authentication successful:', passport);
            return passport;
            
        } catch (error) {
            console.error('Authentication failed:', error);
            throw error;
        }
    }
    
    async getPassport(address) {
        // Mock passport retrieval
        return {
            id: 1234,
            owner: address,
            dataHash: '0xabcdef...',
            created: Date.now() - 86400000 // 1 day ago
        };
    }
    
    async storeContext(contextData) {
        try {
            if (!this.signer) {
                throw new Error('Not authenticated');
            }
            
            // Mock context storage
            const encryptedData = this.mockEncrypt(contextData);
            
            console.log('Storing context:', {
                data: contextData,
                encrypted: encryptedData,
                timestamp: Date.now()
            });
            
            // Simulate blockchain transaction
            await this.mockTransaction('storeContext');
            
            return {
                success: true,
                contextId: Math.floor(Math.random() * 10000),
                dataHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join('')
            };
            
        } catch (error) {
            console.error('Context storage failed:', error);
            throw error;
        }
    }
    
    async getMyLatestContext() {
        try {
            if (!this.signer) {
                throw new Error('Not authenticated');
            }
            
            // Mock context retrieval
            const mockContext = {
                contextId: 1234,
                data: JSON.stringify({
                    preferences: {
                        theme: 'dark',
                        categories: ['tech', 'crypto', 'web3']
                    },
                    readingHistory: [
                        { postId: 1, title: 'Introduction to Web3', timestamp: Date.now() - 3600000 },
                        { postId: 2, title: 'DeFi Explained', timestamp: Date.now() - 7200000 }
                    ]
                }),
                timestamp: Date.now()
            };
            
            return mockContext;
            
        } catch (error) {
            console.error('Context retrieval failed:', error);
            throw error;
        }
    }
    
    async streamPay(recipientAddress, ratePerMinute) {
        try {
            if (!this.signer) {
                throw new Error('Not authenticated');
            }
            
            console.log('Starting payment stream:', {
                recipient: recipientAddress,
                rate: ratePerMinute,
                currency: 'USDC'
            });
            
            // Mock Superfluid stream creation
            await this.mockTransaction('createStream');
            
            return {
                success: true,
                streamId: 'stream_' + Math.floor(Math.random() * 10000),
                recipient: recipientAddress,
                flowRate: ratePerMinute,
                token: 'USDC'
            };
            
        } catch (error) {
            console.error('Payment stream failed:', error);
            throw error;
        }
    }
    
    async stopStream(streamId) {
        try {
            if (!this.signer) {
                throw new Error('Not authenticated');
            }
            
            console.log('Stopping payment stream:', streamId);
            
            await this.mockTransaction('deleteStream');
            
            return {
                success: true,
                streamId: streamId
            };
            
        } catch (error) {
            console.error('Stop stream failed:', error);
            throw error;
        }
    }
    
    async getActiveStreams() {
        try {
            if (!this.signer) {
                throw new Error('Not authenticated');
            }
            
            // Mock active streams
            return [
                {
                    streamId: 'stream_1234',
                    recipient: '0x742d35Cc6635C0532925a3b8D6b9DdE3C0532925',
                    flowRate: 0.01,
                    token: 'USDC',
                    created: Date.now() - 1800000 // 30 min ago
                }
            ];
            
        } catch (error) {
            console.error('Get streams failed:', error);
            throw error;
        }
    }
    
    // Mock helper methods
    mockEncrypt(data) {
        // In real implementation, this would use AES-256-GCM
        return btoa(data);
    }
    
    mockDecrypt(encryptedData) {
        // In real implementation, this would decrypt AES-256-GCM
        return atob(encryptedData);
    }
    
    async mockTransaction(method) {
        // Simulate blockchain transaction delay
        await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 2000));
        
        console.log(`Mock transaction completed: ${method}`);
        
        return {
            hash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
            blockNumber: Math.floor(Math.random() * 1000000),
            gasUsed: Math.floor(Math.random() * 100000)
        };
    }
}

// Load ethers.js if not already loaded
if (typeof window.ethers === 'undefined') {
    const script = document.createElement('script');
    script.src = 'https://cdn.ethers.io/lib/ethers-5.7.2.umd.min.js';
    script.onload = () => {
        console.log('Ethers.js loaded');
    };
    document.head.appendChild(script);
}

// Make OpenContextClient available globally
window.OpenContextClient = OpenContextClient;